type ConversationMoveName = keyof typeof CONVERSATION_MOVES;
type InputsOf<M extends ConversationMoveName> = Extract<(typeof CONVERSATION_MOVES)[M]["sets"][keyof (typeof CONVERSATION_MOVES)[M]["sets"]], MoveInputName>;
/** The values a move's columns take, one per input it names; none for a move that only clears. */
type MoveInput<M extends ConversationMoveName> = {
    [K in InputsOf<M>]: string;
};
